/* ================================================================
   ТЕКСТЫ, ССЫЛКИ И ПРОЕКТЫ САЙТА
   ----------------------------------------------------------------
   Это единственный файл, который нужно править, чтобы поменять
   содержимое сайта. Код в app.js трогать не нужно.

   КАК УСТРОЕНЫ ТЕКСТЫ
   Почти каждый текст записан парой в квадратных скобках:
       ['формальная версия', 'дружеская версия']
   Первая строка видна в светлой версии, вторая — в темной.
   Если текст в обеих версиях одинаковый, можно написать просто
       'одна строка'

   ТИПОГРАФИКА РАССТАВЛЯЕТСЯ САМА (по правилам «Ководства»)
   Пишите как удобно — сайт исправит при показе:
     "кавычки"        → «кавычки», вложенные — „лапки“
     слово - слово    → слово — слово (длинное тире, привязанное к слову)
     60-120           → 60–120 (короткое тире в диапазоне чисел)
     в доме, и я      → предлоги и союзы не повиснут в конце строки
     бы, же, ли       → частицы не оторвутся от предыдущего слова
     60 минут         → число не оторвется от слова
     МТС, LEGO        → прописные получат разрядку
   Букву ё ставьте только там, где без нее можно прочитать
   неправильно (все/всё). Многоточие — три точки.
   Вы — всегда с маленькой буквы.
   Чтобы перенести строку в нужном месте, поставьте \n.

   ВАЖНО ДЛЯ ЗАПИСИ
   - Каждая строка — в одинарных кавычках '...'.
   - Если внутри текста нужен апостроф, поставьте перед ним \'
   - После каждого элемента списка — запятая.
   ================================================================ */

