            solution: 'Взяли старые фотографии селебрити, чтобы подчеркнуть, как долго они уже пользуются платформой. Каждый макет — чье-то «первое»: первый лайк, первый трек, первый друг, первый тренд, первый хайп — и вопрос «А что для тебя было первым ВКонтакте?». Макеты связали с видеороликом, который показывал изменения во времени и значимость ВКонтакте в жизни этих знаменитостей. Так кампания вызвала ностальгию и привлекла внимание к долгой истории соцсети и ее актуальности.',
